import styled from '@emotion/styled';
import { EmptyState } from '@hexa-ui/components';
import { theme } from 'theme';

type EmptyStateFont = 'small' | 'basis' | 'large';
type EmptyStateColor = 'primary' | 'secondary';
type EmptyStateSize = 'auto';

interface StyledEmptyStateProps {
  $font?: EmptyStateFont;
  $color?: EmptyStateColor;
  $size?: EmptyStateSize;
}

export const StyledEmptyState = styled(EmptyState.PageLevel, {
  shouldForwardProp: (propName) =>
    !['$font', '$color', '$size'].includes(propName),
})<StyledEmptyStateProps>(
  ({ $font = 'basis', $color = 'secondary', $size }) => ({
    width: '230px',
    color: theme.colors.txt.secondary,
    maxWidth: '100%',

    h2: {
      fontSize: '16px',
    },

    p: {
      fontSize: '12px',
      color: '#1414148F',
    },

    ...($font === 'small' && { fontSize: theme.fonts.fontSizes['2'] }),
    ...($font === 'basis' && { fontSize: theme.fonts.fontSizes['3'] }),
    ...($font === 'large' && { fontSize: theme.fonts.fontSizes['4'] }),
    ...($color === 'primary' && { color: theme.colors.txt.default }),
    ...($color === 'secondary' && { color: theme.colors.txt.secondary }),
    ...($size === 'auto' && {
      width: 'auto',
      p: { width: 'auto' },
    }),
  }),
);
